`timescale 1ns / 1ps
//=============================================================================
// Testbench: tb_poly_compress
// Tests all 3 compression modes (d=1, d=4, d=10) using KAT vectors
// from the HLS golden model (poly_data.h)
//=============================================================================

module tb_poly_compress();

    // =========================================================
    // 1. DUT Signals
    // =========================================================
    logic        clk;
    logic        rst_n;
    logic        start;
    logic [1:0]  d_sel;
    logic        done;

    logic [6:0]  coeff_addr;
    logic [15:0] coeff_a0;
    logic [15:0] coeff_a1;

    logic        byte_we;
    logic [8:0]  byte_addr;
    logic [7:0]  byte_dout;

    // =========================================================
    // 2. Input Coefficient RAM (128 × 2 × 16-bit)
    // =========================================================
    logic [15:0] input_ram_a0 [0:127];
    logic [15:0] input_ram_a1 [0:127];

    // Synchronous read with 1-cycle latency
    always @(posedge clk) begin
        coeff_a0 <= input_ram_a0[coeff_addr];
        coeff_a1 <= input_ram_a1[coeff_addr];
    end

    // =========================================================
    // 3. Output Byte RAM (capture writes)
    // =========================================================
    logic [7:0] output_ram [0:383]; // max for d=10 is 320, d=12 is 384

    always @(posedge clk) begin
        if (byte_we)
            output_ram[byte_addr] <= byte_dout;
    end

    // =========================================================
    // 4. DUT Instantiation
    // =========================================================
    poly_compress dut (
        .clk(clk),
        .rst_n(rst_n),
        .start(start),
        .d_sel(d_sel),
        .done(done),
        .coeff_addr(coeff_addr),
        .coeff_a0(coeff_a0),
        .coeff_a1(coeff_a1),
        .byte_we(byte_we),
        .byte_addr(byte_addr),
        .byte_dout(byte_dout)
    );

    // =========================================================
    // 5. Clock & Performance Counter
    // =========================================================
    always #5 clk = ~clk;

    integer cycle_count;
    logic   is_running;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycle_count <= 0;
            is_running  <= 0;
        end else begin
            if (start) begin
                cycle_count <= 0;
                is_running  <= 1;
            end else if (done) begin
                is_running  <= 0;
            end else if (is_running) begin
                cycle_count <= cycle_count + 1;
            end
        end
    end

