    // =========================================================
    // 7. Test Execution
    // =========================================================
    integer tc, i, errors;
    integer total_errors = 0;

    task load_input(int tc_num);
        for (int j = 0; j < 128; j++) begin
            input_ram_a0[j] = INPUT_POLY[tc_num][2*j];
            input_ram_a1[j] = INPUT_POLY[tc_num][2*j+1];
        end
    endtask

    task run_and_wait();
        @(negedge clk);
        start = 1;
        @(negedge clk);
        start = 0;
        wait(done);
        @(negedge clk);
    endtask

    initial begin
        clk    = 0;
        rst_n  = 0;
        start  = 0;
        d_sel  = 0;

        $display("=================================================");
        $display("   STARTING BATCH TEST: POLY COMPRESS            ");
        $display("=================================================");

        #20;
        rst_n = 1;
        #10;

        // ===== TEST d=10 (Compress U) =====
        $display("-------------------------------------------------");
        $display(">> TESTING d=10 (Compress U) — 5 test cases");
        for (tc = 0; tc < 5; tc++) begin
            load_input(tc);
            d_sel = 2'b10;
            run_and_wait();

            $display("   [PERFORMANCE] Compress d=10 TC%0d took %0d cycles", tc, cycle_count);

            errors = 0;
            for (i = 0; i < 320; i++) begin
                if (output_ram[i] !== EXP_COMP_U[tc][i]) begin
                    if (errors < 5)
                        $display("   [ERROR] d=10 TC%0d byte %0d: Got %0d, Exp %0d", tc, i, output_ram[i], EXP_COMP_U[tc][i]);
                    errors++;
                end
            end
            if (errors == 0) $display("   >> [PASS] Compress d=10 TC%0d", tc);
            else begin
                $display("   >> [FAIL] Compress d=10 TC%0d — %0d errors", tc, errors);
                total_errors += errors;
            end
        end

        // ===== TEST d=4 (Compress V) =====
        $display("-------------------------------------------------");
        $display(">> TESTING d=4 (Compress V) — 5 test cases");
        for (tc = 0; tc < 5; tc++) begin
            load_input(tc);
            d_sel = 2'b01;
            run_and_wait();

            $display("   [PERFORMANCE] Compress d=4 TC%0d took %0d cycles", tc, cycle_count);

            errors = 0;
            for (i = 0; i < 128; i++) begin
                if (output_ram[i] !== EXP_COMP_V[tc][i]) begin
                    if (errors < 5)
                        $display("   [ERROR] d=4 TC%0d byte %0d: Got %0d, Exp %0d", tc, i, output_ram[i], EXP_COMP_V[tc][i]);
                    errors++;
                end
            end
            if (errors == 0) $display("   >> [PASS] Compress d=4 TC%0d", tc);
            else begin
                $display("   >> [FAIL] Compress d=4 TC%0d — %0d errors", tc, errors);
                total_errors += errors;
            end
        end

        // ===== TEST d=1 (Compress Msg) =====
